<form method="post" enctype="multipart/form-data" class="card hr-onboarding" data-hr-wizard>
<?php hr_fields($staff['id']?'save_profile':'create',(int)$staff['id'],(int)$staff['version']);?>
<nav class="hr-wizard-steps" aria-label="Onboarding steps"><?php foreach(['Personal','Employment','Emergency','Onboarding','Review'] as $i=>$label):?><button type="button" class="secondary" data-hr-step="<?=$i?>" <?=$i===0?'aria-current="step"':''?>><?=$i+1?> · <?=access_h($label)?></button><?php endforeach?></nav>
<section data-hr-panel="0"><h2>Start with the person.</h2><div class="grid"><?php foreach(['name'=>'Full name','preferred'=>'Preferred name','email'=>'Staff email','phone'=>'Phone','dob'=>'Date of birth','address'=>'Residential address'] as $key=>$label)hr_input($label,$key,$data[$key] ?? '',match($key){'email'=>'email','dob'=>'date',default=>'text'},$key==='name');?></div></section>
<section data-hr-panel="1"><h2>A clear place in the team.</h2><div class="grid"><?php foreach(['job'=>'Job title','department'=>'Department','supervisor'=>'Supervisor','employment'=>'Employment type','start'=>'Start date','probation'=>'Probation review date'] as $key=>$label)hr_input($label,$key,$data[$key] ?? '',in_array($key,['start','probation'])?'date':'text',false);?></div></section>
<section data-hr-panel="2"><h2>Someone we can reach.</h2><div class="grid"><?php foreach(['contact_name'=>'Emergency contact name','relationship'=>'Relationship','contact_phone'=>'Emergency phone'] as $key=>$label)hr_input($label,$key,$data[$key] ?? '');?></div><?php hr_textarea('Contact notes','notes',$data['notes'] ?? '');?></section>
<section data-hr-panel="3"><h2>Ready for their first day.</h2><?php foreach(['contract'=>'Signed employment contract','identity'=>'Identity verified','sop'=>'SOP orientation completed','safety'=>'Safety briefing completed','training'=>'Role training completed'] as $key=>$label):?><label class="hr-check"><input type="checkbox" name="<?=$key?>" value="1" <?=!empty($data[$key])?'checked':''?>><?=access_h($label)?></label><?php if(in_array($key,['contract','identity'])&&$can('hr.documents')):?><div class="hr-upload"><?php $preferredType=0;foreach($catalogue['document'] as $type){if($type['name']===($key==='contract'?'Signed employment contract':'Identity document'))$preferredType=(int)$type['id'];}hr_catalogue_select('Supporting document type',$key.'_type_id',$catalogue['document'],$preferredType);?><label class="hr-field">Upload <?=$key==='contract'?'signed contract':'ID document'?> · optional<input name="<?=$key?>_file<?=$key==='identity'?'[]':''?>" type="file" <?=$key==='identity'?'multiple':''?> accept=".pdf,.jpg,.jpeg,.png"><small>PDF/JPG/PNG, up to 5 MB. Uploading does not mark verification complete.</small></label></div><?php endif?><?php endforeach?><p class="muted">Contract, identity verification and SOP orientation are checked at activation. Digital copies remain optional.</p></section>
<section data-hr-panel="4"><h2>Save And Review</h2><p>Save the staff record first. The System access tab lets an authorised administrator link an existing user or issue a new account invitation.</p><p class="muted">Linking retains the original account ID, password, roles and historical attribution. Draft HR records do not deactivate an existing account.</p><p>Save this draft, review the profile and onboarding checklist, then approve activation from Employment.</p></section>
